This Terraform configuration creates an AWS S3 bucket for storing website images. The bucket is configured to allow public read access to objects so images can be displayed on a website. It also enables versioning, configures CORS for browser access, and outputs the bucket name and public URL format for uploaded images.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the image storage bucket will be created."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name. A random suffix will be added to ensure global uniqueness."
  type        = string
  default     = "website-images"
}

variable "allowed_cors_origins" {
  description = "Origins allowed to access images from the bucket. Use your website domain in production."
  type        = list(string)
  default     = ["*"]
}

